".mf section.block{padding:95px 0}.mf .light{background:var(--white)}.mf .soft{background:#ebeee9}.mf .darkblock{background:var(--dark);color:white}.mf .darkblock .lead,.mf .darkblock .muted{color:#c3cfc6}.mf .split{display:grid;grid-template-columns:1fr 1fr;gap:24px}.mf .three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:19px}.mf .four{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.mf .panel{padding:35px 32px;min-height:235px;background:var(--paper);border:1px solid var(--line);border-radius:3px}.mf .panel.white{background:#fff}.mf .panel.dark{background:#283b31;color:#fff;border-color:#435a4c}.mf .panel p{color:#626c64}.mf .panel.dark p{color:#d4dfd7}.mf .panel .ey{margin-bottom:22px}.mf .panel h3{margin-bottom:20px}.mf .tile{background:#e4e9e2;border:1px solid var(--line);padding:26px;min-height:235px;display:flex;flex-direction:column;justify-content:flex-end}.mf .tile .ey{margin-bottom:auto}.mf .tile h3{font-size:29px}.mf .tile p{font-size:13px;color:#56635b}.mf .status{display:inline-block;text-transform:uppercase;font-size:10px;letter-spacing:.09em;font-weight:800;color:#536c5c;background:#e0e9df;padding:6px 10px;border-radius:30px;margin-bottom:12px}.mf .feature-list{padding:0;list-style:none;margin:20px 0}.mf .feature-list li{padding:12px 0;border-top:1px solid var(--line);font-size:14px}.mf .feature-list li:last-child{border-bottom:1px solid var(--line)}",
".mf .photo{width:100%;height:auto;max-height:530px;object-fit:contain;background:#e7e8e5;border:1px solid var(--line)}.mf .photo-caption{font-size:11px;color:#647168;margin-top:8px}.mf .two-col{display:grid;grid-template-columns:1.06fr .94fr;gap:55px;align-items:center}.mf .steps{counter-reset:step}.mf .step{padding:25px 0;border-bottom:1px solid var(--line)}.mf .step b{display:inline-block;width:45px;color:var(--green);font-size:12px}.mf .step strong{font-family:Georgia,serif;font-weight:400;font-size:25px}.mf .mockup{background:#101c17;color:#fff;padding:24px;border-radius:16px;max-width:520px;box-shadow:0 20px 50px rgba(0,0,0,.11)}.mf .mockup .value{font-size:61px;letter-spacing:-.08em;font-family:Georgia,serif}.mf .mockup .bar{height:7px;background:linear-gradient(90deg,#799d84 70%,#334339 70%);border-radius:4px;margin:17px 0}.mf .mockup .minilabel{font-size:11px;text-transform:uppercase;letter-spacing:.13em;color:#bdc9c0}.mf .mockup .prototype{font-size:11px;color:#aebcb0}",
".mf .place{min-height:260px;background:#e5e8e1;border:1px solid #d8ddd5;display:flex;flex-direction:column;justify-content:space-between;padding:24px}.mf .place:nth-child(2){background:#eae8e2}.mf .place:nth-child(3){background:#dfe6df}.mf .place:nth-child(4){background:#e5e8e8}.mf .place .number{font-family:Georgia,serif;font-size:62px;color:#a7b6a9;line-height:1}.mf .place h3{font-size:27px;margin:0}.mf .place p{font-size:12px;margin:6px 0 0}.mf .foot{background:#121f18;color:#f5f6f1;padding:63px 0 38px}.mf .footgrid{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:25px}.mf .foot a{display:block;font-size:12px;text-decoration:none;margin:8px 0;color:#c6d3c9}.mf .foot .ey{color:#aac2ae}.mf .foot p{font-size:12px;color:#bbcbbf}.mf .footlast{margin-top:42px;padding-top:23px;border-top:1px solid #46564b}.mf .footlast a{display:inline-block;margin-right:15px}",
".mf .formpage{max-width:920px;margin:auto}.mf form{background:#fff;border:1px solid var(--line);padding:35px}.mf .formgrid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.mf form label{display:block;font-size:12px;font-weight:750;margin:10px 0 5px}.mf form input,.mf form select{border:1px solid #aeb7ae;border-radius:2px;background:#fafbf9;width:100%;padding:14px;min-height:47px;color:var(--ink)}.mf form .consent{display:flex;gap:10px;align-items:flex-start;font-size:12px;font-weight:400;margin:20px 0}.mf form .consent input{min-height:0;width:18px;margin:3px 0 0}.mf .hint{font-size:12px;color:var(--muted)}.mf .formstatus{padding:12px 0;font-size:13px}.mf .hp{position:absolute!important;left:-99999px!important;opacity:0}.mf .formside{background:#e8ede8;padding:26px;align-self:start}.mf .mobile-ctas{display:none}",
"@media(max-width:1220px){.mf .nav,.mf .topcta,.mf .language{display:none}.mf .mobile-menu{display:block;margin-left:auto}.mf .mobile-menu nav{position:absolute;top:72px;right:12px;left:12px;background:#fbfbf8;border:1px solid var(--line);padding:18px;box-shadow:0 20px 30px rgba(0,0,0,.1)}.mf .mobile-menu nav a{display:block;padding:11px 5px;text-decoration:none;border-bottom:1px solid var(--line);font-size:13px}.mf .mobile-menu nav .langs{padding-top:10px}.mf .mobile-menu nav .langs a{display:inline-block;border:0;padding:5px}}",
"@media(max-width:800px){.mf .container{padding:0 20px}.mf section.block{padding:65px 0}.mf .split,.mf .three,.mf .four,.mf .two-col,.mf .footgrid,.mf .formgrid{grid-template-columns:1fr}.mf .hero{min-height:560px}.mf .hero .container{padding-top:80px;padding-bottom:70px}.mf .hero.image{background:linear-gradient(90deg,rgba(13,27,20,.93),rgba(13,27,20,.75)),url('/assets/images/real-case/komo-case-open.jpeg') center/cover}.mf .hero h1{font-size:clamp(43px,11vw,66px)}.mf .panel{min-height:200px;padding:27px}.mf .place{min-height:190px}.mf form{padding:20px}.mf .mobile-ctas{display:flex;position:sticky;bottom:0;z-index:40;background:#f8f8f4;padding:9px 13px;gap:8px;box-shadow:0 -3px 20px rgba(0,0,0,.12)}.mf .mobile-ctas a{width:50%;padding:10px 6px;font-size:10px;min-height:43px}.mf .mockup .value{font-size:52px}.mf .foot{padding-bottom:78px}}",
