await writeAt("fr/check-ups/phenotype/index.html",page("fr","future"));
await writeAt("fr/check-ups/complete/index.html",page("fr","assessment"));
await writeAt("fr/check-ups/private/index.html",page("fr","anywhere"));
await writeAt("fr/motion-case/index.html",page("fr","case"));
