let sm=await readFile(join(ROOT,"sitemap.xml"),"utf8").catch(()=>'<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"></urlset>');
sm=sm.replace(/<url>\s*<loc>https:\/\/komolongevity\.com\/fr\/check-ups\/(?:phenotype|complete|private)\/<\/loc>[\s\S]*?<\/url>/g,"");
for(const uri of sitemapEntries){let loc=BASE+uri;if(!sm.includes("<loc>"+loc+"</loc>"))sm=sm.replace("</urlset>","<url><loc>"+loc+"</loc></url>\n</urlset>");}
await writeAt("sitemap.xml",sm);
