for(const val of ["MOTION CASE","MOTION BENCH","MOTION LAB","KŌMØ Professional","DEMANDER UN BILAN","ÉQUIPER MON ÉTABLISSEMENT"])if(!test.includes(val))throw Error("Missing home "+val);
